#shade-heat { overflow-wrap: anywhere; }
#shade-heat .shade-fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr)); gap: 12px; padding: 15px 0; }
#shade-heat .shade-fields[hidden] { display: none; }
#shade-heat input, #shade-heat select, #shade-heat textarea { min-width: 0; width: 100%; box-sizing: border-box; }
#shade-heat textarea { resize: vertical; font: inherit; }
#shade-heat #shade-sky-profile-input[hidden] { display: none; }
#shade-heat #shade-sky-weight-bins caption { text-align: left; font-weight: 600; margin-bottom: .5rem; }
#shade-heat input[type=checkbox] { width: auto; margin: 0 .5rem 0 0; vertical-align: middle; }
#shade-heat input[type=file] { max-width: 260px; display: block; }
#shade-heat .shade-file { display: block; font-size: .85rem; }
#shade-heat details { margin: 14px 0; }
#shade-heat summary { cursor: pointer; font-weight: 600; }
#shade-heat svg { display: block; width: 100%; max-height: 340px; margin-top: 14px; }
#shade-heat svg text { font-size: 13px; fill: #45584f; }
#shade-heat .shade-cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
#shade-heat .shade-card { padding: 16px; border: 1px solid #d6e3dd; border-radius: 10px; background: #f4f8f5; }
#shade-heat .shade-card span, #shade-heat .shade-card strong { display: block; }
#shade-heat .shade-card strong { font-size: clamp(1.1rem, 2.5vw, 1.7rem); line-height: 1.35; }
#shade-heat .shade-card.existing { border-top: 3px solid #b56b3b; }
#shade-heat .shade-card.proposal { border-top: 3px solid #167467; }
#shade-heat #shade-inspect { padding: 16px; background: #fafbf7; border-radius: 10px; }
#shade-heat table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: .85rem; }
#shade-heat th, #shade-heat td { text-align: left; padding: 8px 6px; border-bottom: 1px solid #dce6df; overflow-wrap: anywhere; }
#shade-heat #shade-status[data-state=refused], #shade-heat #shade-status[data-state=file-refused] { color: #863e27; }
@media (max-width: 500px) { #shade-heat .shade-cards { gap: 8px; } #shade-heat .shade-card { padding: 10px; } #shade-heat #shade-inspect { padding: 10px; } }

/* Sampling comparison remains part of the existing shade/heat investigation. */
#shade-sampling { border-top: 2px solid #dce6df; margin-top: 28px; padding-top: 18px; min-width: 0; }
#shade-sampling .shade-sampling-selectors { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
#shade-sampling .shade-sampling-legend { display: flex; flex-wrap: wrap; gap: 8px 24px; padding-left: 20px; font-weight: 650; }
#shade-sampling .shade-sampling-table { margin: 18px 0; min-width: 0; max-width: 100%; }
#shade-sampling .shade-sampling-caption { text-align: left; font-weight: 650; margin: 0 0 .4rem; }
#shade-sampling .shade-sampling-scroll { overflow-x: auto; max-width: 100%; }
#shade-sampling .shade-sampling-scroll:focus-visible { outline: 2px solid #146e9e; outline-offset: 3px; }
#shade-sampling table { min-width: 600px; table-layout: auto; }
#shade-sampling table caption { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
#shade-sampling #shade-sampling-inspect { background: #f3f8f6; padding: 14px; border-radius: 8px; }
#shade-sampling #shade-sampling-inspect table { min-width: 300px; }
#shade-sampling .shade-sampling-forcing > div { border-top: 1px solid #dce6df; margin-top: 12px; padding-top: 6px; }
#shade-sampling-status[data-state="refused"], #shade-sampling-status[data-state="file-refused"] { color: #863e27; }
